def next_smallest_palindrome(n):
    # Check if n is already a palindrome
    while str(n) == str(n)[::-1]:
        n += 1

    # If not, increment the last digit and check again
    while True:
        n += 1
        if str(n) == str(n)[::-1]:
            return n
